<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowRight, Check, CircleHelp, Send, UserRound } from 'lucide-vue-next'
import { useRoute, useRouter } from 'vue-router'
import AsyncState from '@/components/shared/AsyncState.vue'
import PageHeader from '@/components/shared/PageHeader.vue'
import ResumeUploadField from '@/components/onboarding/ResumeUploadField.vue'
import { usePlanningConversationStore } from '@/stores/planningConversation'

interface ConversationMessage { id: string; role: 'assistant' | 'user'; content: string }

const route = useRoute(); const router = useRouter(); const planning = usePlanningConversationStore(); const answer = ref(''); const selected = ref('')
const session = computed(() => planning.session); const question = computed(() => session.value?.nextQuestion ?? null)
const messages = computed<ConversationMessage[]>(() => (session.value?.turns ?? []).flatMap((turn) => [{ id: turn.id + '-prompt', role: 'assistant' as const, content: turn.prompt }, { id: turn.id + '-answer', role: 'user' as const, content: turn.answer }]))
const confirmedAnswers = computed(() => Object.entries(session.value?.answers ?? {}).filter(([key]) => key !== 'goal'))
const labels: Record<string, string> = { experience: '已有经验', priority_domain: '优先方向', weekly_minutes: '每周投入', outcome: '预期产出' }

onMounted(() => void planning.load(String(route.params.sessionId)))
function choose(value: string) { selected.value = value; answer.value = value }
function structuredValue(): unknown { if (question.value?.key === 'weekly_minutes') return answer.value.includes('少于') ? 90 : answer.value.includes('4 小时以上') ? 300 : 180; return answer.value }
async function submit() {
  if (!question.value || !answer.value.trim()) return
  const updated = await planning.answer({ stepKey: question.value.key, answer: answer.value.trim(), structuredValue: structuredValue() }); answer.value = ''; selected.value = ''
  if (updated.status === 'ready' && updated.draftRoadmapId) await router.push({ name: 'roadmap-preview', params: { roadmapId: updated.draftRoadmapId } })
}
function displayValue(value: unknown) { return typeof value === 'string' ? value : typeof value === 'number' ? value + ' 分钟' : JSON.stringify(value) }
async function uploadResume(payload: { file: File | null; valid: boolean }) { if (payload.valid && payload.file) await planning.uploadResume(payload.file) }
</script>

<template>
  <div class="page planning-page"><AsyncState :loading="planning.loading" :error="planning.error"><template #default><PageHeader eyebrow="01 · Plan together" title="先聊清楚你想走向哪里。" description="把目标、经验和现实投入告诉规划助手。它会边听边确认重点，再整理成一张可以调整的路线图。" :meta="['自然表达', '边聊边确认', '路线可调整']" />
    <div v-if="session" class="planning-layout"><section class="conversation-panel" aria-labelledby="conversation-title"><div class="conversation-header"><div class="conversation-kicker"><CircleHelp :size="15" aria-hidden="true" /><span id="conversation-title">规划助手 · 第 {{ Math.max(session.currentStep, 1) }} 步</span></div><span class="conversation-state">原话会保留</span></div><div class="message-list"><article v-for="message in messages" :key="message.id" class="message" :class="message.role"><div class="message-avatar"><CircleHelp v-if="message.role === 'assistant'" :size="13" aria-hidden="true" /><UserRound v-else :size="13" aria-hidden="true" /></div><div class="message-body"><small>{{ message.role === 'assistant' ? '规划助手' : '你' }}</small><p>{{ message.content }}</p></div></article><article v-if="question" class="message assistant active-message"><div class="message-avatar"><CircleHelp :size="13" aria-hidden="true" /></div><div class="message-body"><small>规划助手 · 现在</small><p>{{ question.prompt }}</p></div></article></div><div v-if="question?.options?.length" class="quick-replies" aria-label="快捷回答"><button v-for="option in question.options" :key="option" type="button" :class="{ selected: selected === option }" @click="choose(option)">{{ option }}<Check v-if="selected === option" :size="13" aria-hidden="true" /></button></div><form class="conversation-composer" @submit.prevent="submit"><textarea v-model="answer" rows="3" :placeholder="question?.key === 'summary' ? '确认路线，或告诉我还想调整什么' : '用自己的话回答，可以补充具体背景'" :aria-label="question ? question.prompt : '输入回答'" @keydown.meta.enter.prevent="submit" @keydown.ctrl.enter.prevent="submit" /><button class="primary-button" type="submit" :disabled="planning.loading || !answer.trim()"><Send :size="14" aria-hidden="true" />{{ question?.key === 'summary' ? '生成路线图' : '发送' }}<ArrowRight :size="13" aria-hidden="true" /></button></form></section><aside class="confirmed-panel" aria-labelledby="confirmed-title"><div class="confirmed-heading"><UserRound :size="15" aria-hidden="true" /><span id="confirmed-title">目前已经确认</span></div><div class="goal-note"><small>长期目标</small><strong>{{ session.goal }}</strong></div><div v-if="confirmedAnswers.length" class="answer-list"><div v-for="[key, value] in confirmedAnswers" :key="key"><small>{{ labels[key] ?? key }}</small><span>{{ displayValue(value) }}</span></div></div><div v-else class="empty-confirmed">你说出的内容会出现在这里，成为路线调整的依据。</div><ResumeUploadField v-if="!session.resume" @change="uploadResume" /><div v-else class="resume-attached"><small>简历附件</small><span>{{ session.resume.originalFilename }}</span></div><div class="rule-note">当前规划助手会保存你的原话，并根据已确认的信息生成路线草案。</div></aside></div>
  </template></AsyncState></div>
</template>

<style scoped>
.planning-page { max-width: 1060px; }.planning-layout { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(260px, .75fr); gap: 30px; margin-top: 28px; }.conversation-panel { min-width: 0; }.conversation-header { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding-bottom: 11px; border-bottom: 1px solid var(--line); }.conversation-kicker, .confirmed-heading { display: flex; align-items: center; gap: 8px; color: var(--blue); font: 9px var(--mono); letter-spacing: .35px; text-transform: uppercase; }.conversation-state { color: #8b938e; font: 9px var(--mono); }.message-list { display: grid; gap: 18px; padding: 20px 3px 12px; }.message { display: flex; align-items: start; gap: 10px; max-width: 84%; }.message.user { justify-self: end; flex-direction: row-reverse; }.message-avatar { display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto; width: 27px; height: 27px; border: 1px solid var(--line); background: var(--paper-deep); color: var(--blue); }.message.user .message-avatar { border-color: #ddb79f; background: var(--orange-soft); color: #a55d3e; }.message-body { min-width: 0; }.message-body small { color: #8b938e; font: 8px var(--mono); }.message-body p { margin: 5px 0 0; padding: 10px 12px; border: 1px solid var(--line-soft); background: var(--paper-deep); color: #53605a; font-size: 12px; line-height: 1.65; white-space: pre-wrap; }.message.user .message-body p { border-color: #ead6c7; background: var(--orange-soft); color: #684e40; }.active-message { max-width: 92%; }.active-message .message-body p { border-color: #b5bdf0; background: var(--blue-soft); color: var(--ink); }.quick-replies { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0 0 37px; }.quick-replies button { display: inline-flex; align-items: center; gap: 6px; min-height: 32px; padding: 7px 10px; border: 1px solid var(--line); background: var(--paper); color: #5c6962; font-size: 10px; cursor: pointer; }.quick-replies button:hover, .quick-replies button.selected { border-color: var(--orange); background: var(--orange-soft); color: #995436; }.conversation-composer { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; align-items: end; margin-top: 6px; padding-top: 13px; border-top: 2px solid var(--blue); }.conversation-composer textarea { width: 100%; min-width: 0; padding: 11px 12px; border: 1px solid var(--line); outline: none; background: var(--white); color: var(--ink); font: 12px/1.6 var(--sans); resize: vertical; }.conversation-composer textarea:focus { border-color: var(--blue); }.primary-button { display: inline-flex; align-items: center; gap: 5px; min-height: 36px; padding: 8px 11px; border: 1px solid var(--blue); background: var(--blue); color: var(--white); font-size: 10px; cursor: pointer; }.primary-button:hover { background: var(--blue-deep); }.primary-button:disabled { opacity: .55; cursor: wait; }.confirmed-panel { align-self: start; padding: 15px 0; border-top: 2px solid var(--orange); border-bottom: 1px solid var(--line); }.goal-note { margin-top: 20px; }.goal-note small, .answer-list small { display: block; color: #828984; font: 9px var(--mono); }.goal-note strong { display: block; margin-top: 7px; color: var(--ink); font: 400 18px/1.35 var(--serif); }.answer-list { display: grid; gap: 14px; margin-top: 22px; }.answer-list span { display: block; margin-top: 5px; color: #56625d; font-size: 11px; line-height: 1.5; white-space: pre-wrap; }.empty-confirmed { margin-top: 20px; color: var(--muted); font-size: 11px; line-height: 1.6; }.rule-note { margin-top: 25px; padding-top: 12px; border-top: 1px solid var(--line); color: #858b86; font: 10px/1.6 var(--mono); }
.resume-attached { display: grid; gap: 5px; margin-top: 20px; padding-top: 13px; border-top: 1px solid var(--line); }.resume-attached small { color: #828984; font: 9px var(--mono); }.resume-attached span { overflow: hidden; color: var(--ink); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.resume-attached { display: grid; gap: 5px; margin-top: 20px; padding-top: 13px; border-top: 1px solid var(--line); }.resume-attached small { color: #828984; font: 9px var(--mono); }.resume-attached span { overflow: hidden; color: var(--ink); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
@media (max-width: 760px) { .planning-layout { grid-template-columns: 1fr; gap: 22px; }.confirmed-panel { order: -1; }.message { max-width: 94%; }.conversation-composer { grid-template-columns: 1fr; }.conversation-composer button { justify-content: center; } }
</style>
